"""JSON Schema contracts shared with the plugin (generated by scripts/build_contracts.py)."""

from __future__ import annotations

import json
import re
from functools import lru_cache
from importlib import resources
from typing import Any

from jsonschema import Draft7Validator

from .errors import ContractError


@lru_cache(maxsize=None)
def schema(name: str) -> dict[str, Any]:
    """Load a contract such as ``abilities/commit-post.input`` or ``stages/draft``."""
    path = resources.files("aoq_worker").joinpath("contracts", f"{name}.json")
    return json.loads(path.read_text(encoding="utf-8"))


@lru_cache(maxsize=None)
def _validator(name: str) -> Draft7Validator:
    return Draft7Validator(schema(name))


def stage_schema(name: str) -> dict[str, Any]:
    """Stage output schema as sent to AO (without the draft keywords)."""
    out = dict(schema(f"stages/{name}"))
    out.pop("$schema", None)
    out.pop("title", None)
    return out


# Fields the worker fills in itself after the call; models are never asked for them (D19).
WORKER_FIELDS: dict[str, list[tuple[str, ...]]] = {
    "topic_candidates": [("candidates", "items", "evidence"), ("candidates", "items", "id")],
    # The worker matches every quote to the page fetch_url returned it on (research pre-check).
    "research": [("sources",), ("claims", "items", "source_id"), ("claims", "items", "claim_id")],
    # One image per vision call: the worker knows which image it sent.
    "image_judgement": [("images", "items", "image_key")],
}
# Rules a model cannot be trusted to meet on every item. They are left out of the schema sent to
# AO (where one bad item fails the whole call) and enforced by prune() in the worker instead.
_LOOSE_DROP = ("minLength", "maxLength", "pattern", "minItems", "maxItems", "minimum", "maximum")


def _loosen(node: Any) -> Any:
    if isinstance(node, dict):
        return {k: _loosen(v) for k, v in node.items() if k not in _LOOSE_DROP}
    if isinstance(node, list):
        return [_loosen(v) for v in node]
    return node


def model_schema(name: str) -> dict[str, Any]:
    """Stage schema as sent to AO: types, required fields and enums only, without worker fields."""
    out = _loosen(stage_schema(name))
    for path in WORKER_FIELDS.get(name, []):
        node = out
        for key in path[:-1]:
            node = node["properties"][key] if key != "items" else node["items"]
        node["properties"].pop(path[-1], None)
        if path[-1] in node.get("required", []):
            node["required"] = [r for r in node["required"] if r != path[-1]]
    return out


class _Invalid(Exception):
    pass


SLUG_PATTERN = "^[a-z0-9-]+$"
SLUG_PATTERNS = (SLUG_PATTERN, "^[a-z0-9-]*$")  # the second: a translation may leave it to WordPress
# Letters NFKD does not split into a base letter and a mark.
_ASCII = str.maketrans({"đ": "dj", "Đ": "dj", "ß": "ss", "æ": "ae", "Æ": "ae", "ø": "o", "Ø": "o", "ł": "l", "Ł": "l", "þ": "th", "ı": "i"})


def ascii_slug(text: str) -> str:
    """Lowercase ASCII words joined by hyphens; letters with accents lose them (ž -> z, đ -> dj).
    Letters with no Latin form (Arabic, Cyrillic) are dropped, so the result can be empty."""
    import unicodedata

    text = unicodedata.normalize("NFKD", text.translate(_ASCII)).encode("ascii", "ignore").decode()
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def _prune(node: dict[str, Any], value: Any, path: str, dropped: list[str]) -> Any:
    if Draft7Validator(node).is_valid(value):
        return value
    types = node.get("type")
    types = types if isinstance(types, list) else [types]
    if isinstance(value, dict) and "object" in types and "properties" in node:
        props, required = node["properties"], set(node.get("required", []))
        out: dict[str, Any] = {}
        for key, sub in value.items():
            where = f"{path}/{key}"
            if key not in props:
                if node.get("additionalProperties", True) is False:
                    dropped.append(f"{where} (not in schema)")
                    continue
                out[key] = sub
                continue
            try:
                out[key] = _prune(props[key], sub, where, dropped)
            except _Invalid:
                if key in required:
                    raise
                dropped.append(where)
        if not required <= set(out):
            raise _Invalid(f"{path or '(root)'}: missing {sorted(required - set(out))}")
        if not Draft7Validator(node).is_valid(out):
            raise _Invalid(path or "(root)")
        return out
    if isinstance(value, list) and "array" in types and "items" in node:
        out_list = []
        for i, item in enumerate(value):
            try:
                out_list.append(_prune(node["items"], item, f"{path}/{i}", dropped))
            except _Invalid:
                dropped.append(f"{path}/{i}")
        if "maxItems" in node and len(out_list) > node["maxItems"]:
            dropped.append(f"{path}/{node['maxItems']}.. (over {node['maxItems']} items)")
            out_list = out_list[: node["maxItems"]]
        if len(out_list) < node.get("minItems", 0):
            raise _Invalid(f"{path or '(root)'}: only {len(out_list)} valid item(s), at least {node['minItems']} needed")
        if not Draft7Validator(node).is_valid(out_list):
            raise _Invalid(path or "(root)")
        return out_list
    if isinstance(value, (int, float)) and not isinstance(value, bool) and node.get("maximum") == 1 and node.get("minimum", 0) == 0:
        # A 0-1 score given on a 0-10 or 0-100 scale (phi4 rated SEO 8.0): rescale instead of failing.
        for scale in (10, 100):
            if 1 < value <= scale:
                dropped.append(f"{path} (score {value:g} read as out of {scale})")
                return round(value / scale, 4)
    if isinstance(value, str) and "string" in types and node.get("pattern") in SLUG_PATTERNS:
        # A slug in the language's own letters (run 8140dae6: "istraživanje-…"): made ASCII. Where the
        # contract allows an empty slug (translations), one with no Latin letters left becomes empty and
        # WordPress makes it from the title, as it did for the Arabic site's posts.
        fixed = ascii_slug(value)[: node.get("maxLength", 200)].strip("-")
        if Draft7Validator(node).is_valid(fixed):
            dropped.append(f"{path} (made ASCII: {fixed or 'empty, WordPress makes it from the title'})")
            return fixed
    if isinstance(value, str) and "string" in types and "maxLength" in node and "pattern" not in node and "enum" not in node:
        cut = value[: node["maxLength"]]
        if Draft7Validator(node).is_valid(cut):
            dropped.append(f"{path} (cut to {node['maxLength']} characters)")
            return cut
    raise _Invalid(path or "(root)")


def prune(value: Any, name: str, *, stage: str) -> tuple[Any, list[str]]:
    """Make ``value`` valid under the strict contract by dropping only what is invalid.

    Invalid array items and invalid optional fields are removed, over-long free text is cut and
    surplus items are trimmed. When something required cannot be saved (a required field, or an
    array left below its minimum), a ContractError names it. Returns (value, removed paths).
    """
    dropped: list[str] = []
    try:
        out = _prune(schema(name), value, "", dropped)
    except _Invalid as exc:
        raise ContractError(stage, f"{name} failed validation: {exc}; " + "; ".join(errors(value, name)[:5])) from exc
    validate(out, name, stage=stage)
    return out, dropped


def enums() -> dict[str, list[str]]:
    return schema("enums")


def errors(value: Any, name: str) -> list[str]:
    """Validation errors, empty when valid."""
    return [
        f"{'/'.join(str(p) for p in e.absolute_path) or '(root)'}: {e.message}"
        for e in sorted(_validator(name).iter_errors(value), key=lambda e: list(e.absolute_path))
    ][:20]


def validate(value: Any, name: str, *, stage: str) -> Any:
    problems = errors(value, name)
    if problems:
        raise ContractError(stage, f"{name} failed validation: " + "; ".join(problems))
    return value
